// @ts-nocheck
declare const Deno: any;

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.48.1'

const botToken = Deno.env.get('TELEGRAM_BOT_TOKEN') || '';
const tgUrl = `https://api.telegram.org/bot${botToken}`;
const BOT_USERNAME = 'souqbaghda_bot';

const processedTelegramUpdateIds = new Set<number>();

async function sendMessage(chatId: string | number, text: string, replyMarkup?: any, disableWebPagePreview = true, replyToMessageId?: number | string) {
  const body: any = { 
    chat_id: chatId, 
    text, 
    parse_mode: 'HTML',
    disable_web_page_preview: true,
    link_preview_options: { is_disabled: true }
  };
  if (replyMarkup) {
    body.reply_markup = (replyMarkup && typeof replyMarkup === 'object' && replyMarkup.reply_markup !== undefined)
      ? replyMarkup.reply_markup
      : replyMarkup;
  }
  if (replyToMessageId) body.reply_to_message_id = replyToMessageId;
  try {
    const res = await fetch(`${tgUrl}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (!data.ok) {
      console.warn('sendMessage HTML parse failed, retrying as plain text:', data.description);
      delete body.parse_mode;
      const cleanPlain = text.replace(/<[^>]*>?/gm, '');
      body.text = cleanPlain;
      const resPlain = await fetch(`${tgUrl}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      return await resPlain.json();
    }
    return data;
  } catch (e) {
    console.error('sendMessage fetch exception:', e);
    return { ok: false, error: String(e) };
  }
}

async function answerCallbackQuery(callbackQueryId: string, text: string = '', showAlert = false) {
  try {
    return await fetch(`${tgUrl}/answerCallbackQuery`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ callback_query_id: callbackQueryId, text, show_alert: showAlert })
    });
  } catch (e) {
    return null;
  }
}

async function sendChatAction(chatId: string | number, action = 'typing') {
  fetch(`${tgUrl}/sendChatAction`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, action })
  }).catch(() => {});
}

async function syncTelegramBotCommands() {
  try {
    // 1. Group Chats Scope (Members only see line, seats, help)
    await fetch(`${tgUrl}/setMyCommands`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        commands: [
          { command: 'line', description: '🔍 ابحث عن خط نقل لدوامك' },
          { command: 'seats', description: '💺 نشر مقاعد شاغرة (للكباتن)' },
          { command: 'help', description: '❓ طريقة استخدام البوت ومميزاته' }
        ],
        scope: { type: 'all_group_chats' }
      })
    });

    // 2. Group Admins Scope (Admins additionally see warn, unwarn, mute, ban)
    await fetch(`${tgUrl}/setMyCommands`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        commands: [
          { command: 'line', description: '🔍 ابحث عن خط نقل للجامعة' },
          { command: 'seats', description: '💺 نشر مقاعد شاغرة (للكباتن)' },
          { command: 'warn', description: '⚠️ إنذار عضو مخالف في الكروب' },
          { command: 'unwarn', description: '🍏 إزالة الإنذارات عن عضو' },
          { command: 'mute', description: '🔇 كتم عضو مخالف لمدة ساعة' },
          { command: 'ban', description: '🚫 طرد وحظر عضو مخالف نهائياً' },
          { command: 'help', description: '❓ لوحة المساعدة وقوانين الحماية' }
        ],
        scope: { type: 'all_chat_administrators' }
      })
    });

    // 3. Private Chats Scope (Personal chat for students/passengers/drivers)
    await fetch(`${tgUrl}/setMyCommands`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        commands: [
          { command: 'start', description: '🚀 القائمة الرئيسية وخدمات البوت' },
          { command: 'line', description: '🚌 البحث عن خطوط النقل الجامعي' },
          { command: 'pubtrans', description: '📢 انشر طلب خط أو اعرض مقاعدك' },
          { command: 'help', description: '💬 المساعدة والدعم الفني' }
        ],
        scope: { type: 'all_private_chats' }
      })
    });

    // 4. Owner Scope (Only the Owner sees /owner and /social in private chat)
    await fetch(`${tgUrl}/setMyCommands`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        commands: [
          { command: 'owner', description: '👑 لوحة تحكم المالك الشاملة' },
          { command: 'social', description: '🦅 قنوات السوشيال والتسعير' },
          { command: 'start', description: '🚀 القائمة الرئيسية' }
        ],
        scope: { type: 'chat', chat_id: 6474465462 }
      })
    });

    // 5. Default Fallback Scope
    await fetch(`${tgUrl}/setMyCommands`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        commands: [
          { command: 'start', description: '🚀 تشغيل البوت والخدمات' },
          { command: 'line', description: '🚌 البحث عن خط نقل' },
          { command: 'help', description: '❓ المساعدة' }
        ],
        scope: { type: 'default' }
      })
    });

    console.log('[TELEGRAM BOT] Bot commands scoped successfully for groups, admins, private, and owner!');
  } catch(e) {
    console.error('[TELEGRAM BOT] setMyCommands error:', e);
  }
}

async function callAiEngine(userText: string | null, audioUrl: string | null, photoUrl: string | null, userName?: string, supabase?: any, history?: any[], audioBase64?: string): Promise<string> {
  const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY") ?? "";
  const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY") ?? "";

  const name = userName || 'عزيزنا';
  let dbContext = '';

  const cleanQ = (userText || '').trim().toLowerCase();
  if (['شكرا', 'شكراً', 'مشكور', 'رحم الله والديك', 'عاشت ايدك', 'تسلم', 'تسلمين', 'حبيبي', 'فدوة', 'فدوه', 'ممنون', 'تسلم ايدك', 'مشكور حبيبي'].some(w => cleanQ === w || cleanQ === w + ' عيوني' || cleanQ === w + ' اخويه' || cleanQ === 'شكرا جزيلا' || cleanQ === 'الف شكر')) {
    return `العفو عيوني وتدلل من راسي! 🌹 أنا بالخدمة 24 ساعة، وإذا احتجت أي مساعدة بخطوط النقل أو السيارات أو نشر إعلانك بس اكتبلي وتأمر أمر ✨`;
  }

  // 1. Fetch relevant database context if query asks about cars, prices, transport, or general items
  if (supabase && userText) {
    const q = userText.toLowerCase();
    try {
      if (q.includes('سيار') || q.includes('سعر') || q.includes('بيش') || q.includes('توسان') || q.includes('النترا') || q.includes('كورولا') || q.includes('كامري') || q.includes('سبورتاج') || q.includes('سنتافي') || q.includes('تاهو')) {
        const { data: recentCars } = await supabase.from('ads').select('title, price, location, year').in('category', ['vehicles', 'cars', 'car']).eq('status', 'active').order('created_at', { ascending: false }).limit(6);
        if (recentCars && recentCars.length > 0) {
          dbContext += `\nأحدث السيارات المعروضة بسوق بغداد حالياً:\n` + recentCars.map((c: any) => `- ${c.title} (سعر: ${c.price || 'اتصال'} | ${c.location || 'بغداد'})`).join('\n');
        }
      }
      if (q.includes('خط') || q.includes('نقل') || q.includes('جامع') || q.includes('كلية') || q.includes('رافدين') || q.includes('سايق')) {
        const { data: recentTrans } = await supabase.from('ads').select('title, location, phone').eq('category', 'transport').eq('status', 'active').order('created_at', { ascending: false }).limit(5);
        if (recentTrans && recentTrans.length > 0) {
          dbContext += `\nأحدث خطوط النقل النشطة بسوق بغداد:\n` + recentTrans.map((t: any) => `- ${t.title} (المناطق: ${t.location} | هاتف: ${t.phone})`).join('\n');
        }
      }
    } catch(e) {}
  }

  const systemPrompt = 
    `أنت عقل ومحرك ذكاء اصطناعي فائق التطور مصمم كـ "المستشار والمساعد الذكي الأقوى في العراق" لمنصة سوق بغداد (https://www.souqbaghdad.store).

🧠 شخصيتك وأسلوبك بالحديث:
1. تتحدث بلهجة عراقية بغدادية فصيحة، ذكية جداً، راقية، دافئة، غاية في اللباقة وخفة الظل (مثل: يا هلا بيك عيوني، تدلل يالغالي، فدوة لقلبك، من عيوني، كفو منك).
2. إذا سلم عليك المستخدم (هلو، مرحبا، شلونك، صباح الخير): رد بترحيب عراقي دافئ جداً ومميز واسأله كيف تساعده اليوم (خطوط نقل، سيارات، بيع وشراء، نقاط).
3. تفهم كل تفاصيل الشارع العراقي، المناطق، الجامعات (الرافدين، دجلة، التراث، بغداد، المستنصرية، النهرين، التكنولوجية، الإسراء.. إلخ)، وخطوط النقل والسيارات.
4. التسامح الفوري مع الأخطاء الإملائية والعامية السريعة وافهم قصد المستخدم فوراً وأجبه بدقة واختصار مفيد.

📚 قاعدة معرفتك الشاملة بمنصة سوق بغداد:
• 🪙 **نظام النقاط:** يحصل كل حساب جديد على 100 نقطة مجانية. يمكن كسب نقاط يومية مجانية بتسجيل الدخول، ومشاركة رابط الإحالة، أو إدخال كود الهدية من قسم الحساب.
• 🚌 **خطوط النقل:** نشر الخطوط مجاني وسريع للكباتن بـ 9 خطوات سهلة، مع توليد بطاقة ستوري احترافية ونشرها في قنوات التيليجرام والفيسبوك فوراً. يمكن للكابتن تعديل المقاعد الشاغرة أو إغلاق الخط بضغطة زر.
• 💺 **حجز المقاعد:** يمكن للطلاب حجز مقعد بضغطة زر ترسل إشعاراً عاجلاً لهاتف الكابتن مع محادثة واتساب سريعة.
• 🪪 **توثيق الحسابات:** يمكن للسائق رفع هويته وبطاقة السكن لنيل شارة "كابتن موثوق 🎖️" الذهبية لزيادة ثقة الركاب.
• 🚗 **سوق السيارات والمنتجات:** بيع وشراء السيارات والهواتف والسلع مع أرقام التواصل وميزة "تم البيع" الحية.
• 🔒 **الأمان واسترجاع الرمز:** الحسابات محمية برمز PIN سري يمكن استرجاعه برقم الهاتف الموثق.
${dbContext ? `\n[بيانات حية من قاعدة بيانات سوق بغداد]:\n${dbContext}\n` : ''}`;

  // 1. Google Gemini 2.0 Flash / 1.5 Flash
  if (GEMINI_API_KEY && (userText || audioUrl || photoUrl || audioBase64)) {
    for (const model of ['gemini-2.0-flash', 'gemini-1.5-flash']) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 12000);

        const contents: any[] = [];
        if (history && Array.isArray(history)) {
          for (const h of history.slice(-6)) {
            if (h.role && h.text) {
              contents.push({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.text }] });
            }
          }
        }

        const userParts: any[] = [];
        if (userText) {
          userParts.push({ text: `المستخدم (${name}) يقول:\n${userText}` });
        } else {
          userParts.push({ text: `المستخدم (${name}) أرسل بصمة صوتية:` });
        }

        if (audioBase64) {
          userParts.push({
            inlineData: {
              mimeType: "audio/ogg",
              data: audioBase64
            }
          });
        }

        contents.push({ role: 'user', parts: userParts });

        const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            systemInstruction: {
              parts: [{ text: systemPrompt }]
            },
            contents,
            generationConfig: { maxOutputTokens: 600, temperature: 0.7 }
          }),
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        const data = await resp.json();
        const aiText = data.candidates?.[0]?.content?.parts?.[0]?.text;
        if (aiText && aiText.trim()) return aiText.trim();
      } catch(e) {
        console.warn(`Gemini model ${model} failed:`, e);
      }
    }
  }

  // 2. OpenAI GPT-4o-mini Fallback
  if (OPENAI_API_KEY && userText) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 8000);
      const resp = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: `${name} يقول: "${userText}"` }
          ],
          max_tokens: 500,
          temperature: 0.7
        }),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      const data = await resp.json();
      const aiText = data.choices?.[0]?.message?.content;
      if (aiText && aiText.trim()) return aiText.trim();
    } catch(e) {
      console.warn('OpenAI fallback failed:', e);
    }
  }

  // 3. Dynamic Local Iraqi AI Greetings Fallback
  if (['هلو', 'هلا', 'مرحبا', 'مرحباً', 'سلام', 'السلام عليكم', 'سلام عليكم', 'صباح الخير', 'مساء الخير', 'شلونك', 'شلونك عيني', 'شلونكم'].some(g => cleanQ === g || cleanQ.startsWith(g + ' '))) {
    const greetings = [
      `يا هلا وكل الهلا بيك عيوني ${name} 🌹 نورتنا!\nشلون أكدر أخدمك اليوم؟ تبحث عن خط نقل لجامعتك، أو تدور سيارة نظيفة، أو تحب تنشر إعلان مجاني بسوق بغداد؟ ✨`,
      `أهلاً وسهلاً بيك يالغالي ${name} 🌹 يا رب تكون بألف خير وصحة.\nأنا مستشارك الذكي بسوق بغداد، كلي شنو اللي ببالك وتدلل من عيوني! 🚗🚌`,
      `يا مية هلا بيك عيوني ${name} 🌹 نورت البوت.\nكلي شلون أساعدك اليوم؟ محتاج خط، تدور سيارة، أو عندك استفسار عن الكليات والأسعار؟ 🤝`
    ];
    return greetings[Math.floor(Math.random() * greetings.length)];
  }

  return `يا هلا بيك عيوني ${name} 🌹 أنا في خدمتك دائماً في منصة سوق بغداد. تكدر تبحث عن سيارة أو خط نقل أو تنشر إعلانك مجاناً عبر الأزرار أدناه 👇`;
}

function detectGroupCategory(title: string, desc?: string): 'university' | 'cars' | 'market' | 'general' {
  const t = (title + ' ' + (desc || '')).toLowerCase();
  
  if (
    t.includes('جامع') || t.includes('كلية') || t.includes('قسم ') || t.includes('مرحل') ||
    t.includes('رافدين') || t.includes('مستنصري') || t.includes('تكنولوجي') || t.includes('دكتور') ||
    t.includes('طالب') || t.includes('طلاب') || t.includes('طالبات') || t.includes('نقل') || t.includes('خطوط') || t.includes('خط') || t.includes('باص')
  ) {
    return 'university';
  }

  if (
    t.includes('سيار') || t.includes('سوق السيار') || t.includes('معارض') || t.includes('معرض') ||
    t.includes('وارد') || t.includes('كوريات') || t.includes('توسان') || t.includes('النترا') ||
    t.includes('كيا') || t.includes('هيونداي') || t.includes('تويوتا') || t.includes('شفر') || t.includes('دوج')
  ) {
    return 'cars';
  }

  if (
    t.includes('سوق') || t.includes('بيع') || t.includes('شراء') || t.includes('عقار') ||
    t.includes('موبايل') || t.includes('تجارة') || t.includes('اعلانات') || t.includes('إعلانات')
  ) {
    return 'market';
  }

  return 'general';
}

async function callGroupAiEngine(userText: string, userName: string, groupTitle?: string, contextInfo?: string): Promise<string> {
  const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY") ?? "";
  const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY") ?? "";

  const title = groupTitle || 'الكروب';
  const category = detectGroupCategory(title);

  let groupSpecialty = 'مساعد وخدمة الكروب وحمايته من السبام والإعلانات المزعجة';
  if (category === 'university') {
    groupSpecialty = 'مساعد طلاب وأساتذة الجامعات وخطوط النقل وتوصيل الطلاب والسائقين وحجز المقاعد بدقة';
  } else if (category === 'cars') {
    groupSpecialty = 'خبير سوق ومعارض السيارات وأسعارها وموديلاتها ومساعدة الأعضاء في تقييم وبيع وشراء السيارات';
  } else if (category === 'market') {
    groupSpecialty = 'مساعد البيع والشراء والسوق المفتوح وتسهيل التجارة الآمنة بين الأعضاء';
  }

  const systemPrompt = `أنت المساعد والمستشار الذكي الرسمي من منصة "سوق بغداد" (https://www.souqbaghdad.store) متواجد داخل كروب "${title}" (تخصص الكروب: ${groupSpecialty}).
طريقتك وأسلوبك بالرد:
1. تصرف كـ (موظف ومستشار عراقي شاطر، خلوق، محترم، وخفيف الظل) بلهجة بغدادية لطيفة (مثال: تدلل عيوني، بالخدمة يالغالي، يا هلا بيك).
2. افهم طبيعة ونوع الكروب واجعل جوابك مناسباً جداً لتخصص المجموعة (جامعات/سيارات/سوق عام).
3. الرد قصير ومفيد (سطرين إلى 3 أسطر كحد أقصى) بدون إطالة أو حشو.
4. استخدم حصراً روابط سوق بغداد الرسمية وبوت @${BOT_USERNAME}، وممنوع ذكر أي جهات أو بوتات خارجية نهائياً.
${contextInfo ? `بيانات حية من المنصة:\n${contextInfo}` : ''}`;

  if (GEMINI_API_KEY) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6000);
      const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_API_KEY}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          systemInstruction: {
            parts: [{ text: systemPrompt }]
          },
          contents: [
            { role: 'user', parts: [{ text: `${userName} يقول: "${userText}"` }] }
          ],
          generationConfig: { maxOutputTokens: 200, temperature: 0.7 }
        }),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      const data = await resp.json();
      const aiText = data.candidates?.[0]?.content?.parts?.[0]?.text;
      if (aiText && aiText.trim()) return aiText.trim();
    } catch(e) {}
  }

  if (OPENAI_API_KEY) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 4000);
      const resp = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: `${userName} يكتب: "${userText}"` }
          ],
          max_tokens: 100
        }),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      const data = await resp.json();
      const aiText = data.choices?.[0]?.message?.content;
      if (aiText) return aiText.trim();
    } catch(e) {}
  }

  return `يا هلا بيك عيوني ${userName} 🌹\n` +
         `تصفح خطوط النقل والسيارات مباشرة عبر: https://www.souqbaghdad.store\n` +
         `أو افتح محادثة خاصة مع @${BOT_USERNAME} للنشر والتصفح المجاني ✨`;
}

async function sendPhoto(chatId: string | number, photoUrl: string, caption: string, replyMarkup?: any) {
  try {
    const body: any = { 
      chat_id: chatId, 
      photo: photoUrl, 
      caption, 
      parse_mode: 'HTML'
    };
    if (replyMarkup) body.reply_markup = replyMarkup;
    const res = await fetch(`${tgUrl}/sendPhoto`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (!data.ok) {
      console.warn('sendPhoto failed, attempting fallback photo before text:', data.description);
      const fallbackPhoto = 'https://lyhqnccpudwgvexqinxa.supabase.co/storage/v1/object/public/ad-images/transport-story-OQL5S-1789864881859.png';
      if (photoUrl !== fallbackPhoto) {
        try {
          body.photo = fallbackPhoto;
          const retryRes = await fetch(`${tgUrl}/sendPhoto`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body)
          });
          const retryData = await retryRes.json();
          if (retryData.ok) {
            console.log('[sendPhoto] Recovered successfully using verified fallback photo!');
            return retryData;
          }
        } catch (e2) {
          console.error('[sendPhoto] Fallback photo retry failed:', e2);
        }
      }
      return await sendMessage(chatId, caption, replyMarkup, true);
    }
    return data;
  } catch (e) {
    console.error('sendPhoto exception, falling back to sendMessage:', e);
    return await sendMessage(chatId, caption, replyMarkup, true);
  }
}

// 🧠 Smart Gender Detector from Arabic Names (كشف ذكي لجنس المستخدم من الاسم: طالب / طالبة)
function detectGenderFromName(name: string): 'female' | 'male' | 'unknown' {
  if (!name) return 'unknown';
  const clean = name.trim().toLowerCase();
  
  const femaleNames = [
    'فاطمة', 'فاطمه', 'زهراء', 'زينب', 'مريم', 'سارة', 'ساره', 'نور', 'هدى', 'هديل', 
    'شهد', 'ريم', 'رند', 'آية', 'اية', 'دانية', 'دانيه', 'ياسمين', 'بنين', 'حنين', 
    'طيبة', 'طيبه', 'جنات', 'مروة', 'مروه', 'تبارك', 'رسل', 'إسراء', 'اسراء', 'رقية', 
    'رقيه', 'شمس', 'ورود', 'ملاك', 'دلال', 'فرح', 'تمارا', 'نبأ', 'نبا', 'تقى', 
    'سجى', 'ضحى', 'روان', 'رغد', 'غدير', 'خلود', 'سها', 'شروق', 'إيناس', 'ايناس', 
    'عذراء', 'ولاء', 'نجلاء', 'حوراء', 'زهور', 'ريام', 'يقين', 'أمل', 'امل', 'زينب'
  ];
  
  const words = clean.split(/[\s_\.\-]+/).filter(Boolean);
  if (words.length === 0) return 'unknown';
  const firstWord = words[0];

  if (femaleNames.some(fn => clean.includes(fn) || firstWord === fn)) {
    return 'female';
  }

  // Common feminine patterns in Arabic names
  const exceptionsNotFemale = ['حمزة', 'حمزه', 'أسامة', 'اسامه', 'قتيبة', 'طلحة', 'حذيفة', 'عروة', 'معاوية', 'عبيدة'];
  if ((firstWord.endsWith('ة') || firstWord.endsWith('ه')) && !exceptionsNotFemale.includes(firstWord)) {
    return 'female';
  }
  if (clean.includes('بنت ') || clean.includes('أم ') || clean.includes('ام ')) {
    return 'female';
  }

  const maleNames = [
    'محمد', 'علي', 'احمد', 'أحمد', 'حسين', 'عباس', 'كرار', 'سجاد', 'مصطفى', 'حيدر', 
    'يوسف', 'حسن', 'مهدي', 'عمر', 'عثمان', 'إبراهيم', 'ابراهيم', 'خالد', 'جعفر', 
    'منتظر', 'همام', 'أمير', 'امير', 'سيف', 'عبد', 'رضا', 'باقر', 'صادق', 'حمزة', 
    'اسامة', 'ضرغام', 'مهند', 'ليث', 'زيد', 'عمار', 'فهد', 'عادل', 'ياسر', 'طارق', 
    'كابتن', 'حارث', 'بلال', 'وليد', 'ماجد', 'فراس', 'وسام', 'قصي', 'لؤي', 'بشير'
  ];

  if (maleNames.some(mn => clean.includes(mn) || firstWord === mn) || clean.includes('ابو ') || clean.includes('أبو ') || clean.includes('بن ')) {
    return 'male';
  }

  return 'unknown';
}

