async function transcribeVoiceWithAi(fileUrl: string): Promise<{ text: string | null, base64: string | null }> {
  const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY") ?? "";
  const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY") ?? "";

  try {
    const audioFetch = await fetch(fileUrl);
    if (!audioFetch.ok) return { text: null, base64: null };
    const arrayBuffer = await audioFetch.arrayBuffer();
    const uint8 = new Uint8Array(arrayBuffer);
    
    // Reliable base64 conversion
    let binary = '';
    const len = uint8.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(uint8[i]);
    }
    const base64Audio = btoa(binary);

    // 1. Google Gemini 2.0 Flash Multimodal Audio Transcription
    if (GEMINI_API_KEY) {
      try {
        const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_API_KEY}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{
              role: 'user',
              parts: [
                {
                  text: "أنت نظام استماع وتحويل صوتي دقيق جداً للهجة العراقية البغدادية. استمع للبصمة الصوتية واكتب النص المنطوق بدقة متناهية بدون أي مقدمات أو شروحات:"
                },
                {
                  inlineData: {
                    mimeType: "audio/ogg",
                    data: base64Audio
                  }
                }
              ]
            }],
            generationConfig: { maxOutputTokens: 200, temperature: 0.1 }
          })
        });
        const data = await resp.json();
        const transcription = data.candidates?.[0]?.content?.parts?.[0]?.text;
        if (transcription && transcription.trim()) {
          return { text: transcription.trim().replace(/^["']|["']$/g, ''), base64: base64Audio };
        }
      } catch(e) {
        console.warn('Gemini voice transcription failed:', e);
      }
    }

    // 2. OpenAI Whisper Fallback
    if (OPENAI_API_KEY) {
      try {
        const formData = new FormData();
        const file = new File([uint8], 'voice.ogg', { type: 'audio/ogg' });
        formData.append('file', file);
        formData.append('model', 'whisper-1');
        formData.append('language', 'ar');

        const whisperResp = await fetch('https://api.openai.com/v1/audio/transcriptions', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${OPENAI_API_KEY}` },
          body: formData
        });
        const whisperData = await whisperResp.json();
        if (whisperData?.text) {
          return { text: whisperData.text.trim(), base64: base64Audio };
        }
      } catch(e) {
        console.warn('Whisper voice transcription failed:', e);
      }
    }

    return { text: null, base64: base64Audio };
  } catch(e) {
    console.error('transcribeVoiceWithAi exception:', e);
  }
  return { text: null, base64: null };
}

async function scheduleMessageDeletion(chatId: string | number, botMessageId: number, delayMs = 60000) {
  if (!botMessageId) return;
  try {
    await new Promise(resolve => setTimeout(resolve, delayMs));
    if (botMessageId) await deleteMessage(chatId, botMessageId);
  } catch(e) {}
}

async function unpinChatMessage(chatId: string | number, messageId?: number) {
  try {
    const body: any = { chat_id: chatId };
    if (messageId) body.message_id = messageId;
    await fetch(`${tgUrl}/unpinChatMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
  } catch(e) {}
}

async function sendOrReplaceGroupMessage(chatId: string | number, text: string, markup?: any, supabase?: any, replyToUserMsgId?: number | string, delayMs = 60000) {
  if (supabase) {
    try {
      const { data: lastRecord } = await supabase.from('group_warnings').select('last_reason').eq('chat_id', String(chatId)).eq('user_id', 'BOT_LAST_MSG').maybeSingle();
      if (lastRecord && lastRecord.last_reason) {
        const oldMsgId = parseInt(lastRecord.last_reason);
        if (!isNaN(oldMsgId)) {
          deleteMessage(chatId, oldMsgId);
        }
      }
    } catch(e) {}
  }

  const res = await sendMessage(chatId, text, markup, true, replyToUserMsgId);
  if (res && res.result && res.result.message_id) {
    const newMsgId = res.result.message_id;
    if (supabase) {
      try {
        await supabase.from('group_warnings').upsert({
          chat_id: String(chatId),
          user_id: 'BOT_LAST_MSG',
          username: 'BOT',
          warning_count: 0,
          last_reason: String(newMsgId),
          updated_at: new Date().toISOString()
        });
      } catch(e) {}
    }

    // Keep response visible in group as a brief notice for 60 seconds (60000ms), then delete bot reply automatically
    if (typeof (globalThis as any).EdgeRuntime?.waitUntil === 'function') {
      (globalThis as any).EdgeRuntime.waitUntil(scheduleMessageDeletion(chatId, newMsgId, delayMs));
    }
  }
  return res;
}

function getCoreLocationKeyword(loc: string) {
  if (!loc) return '';
  const s = loc.toLowerCase().replace(/[\u064B-\u065F]/g, ''); // strip tashkeel
  if (s.includes('رافدين') || s.includes('رفدين') || s.includes('ruc')) return 'رافدين';
  if (s.includes('مستنصر') || s.includes('مستنصري')) return 'مستنصرية';
  if (s.includes('تكنولوج') || s.includes('صناع')) return 'تكنولوجية';
  if (s.includes('نهرين')) return 'نهرين';
  if (s.includes('عراقي')) return 'عراقية';
  if (s.includes('اسراء') || s.includes('إسراء')) return 'اسراء';
  if (s.includes('اوروك') || s.includes('أوروك')) return 'اوروك';
  if (s.includes('فراهيد')) return 'فراهيدي';
  if (s.includes('دجل')) return 'دجلة';
  if (s.includes('تراث')) return 'تراث';
  if (s.includes('رشيد')) return 'رشيد';
  if (s.includes('معارف')) return 'معارف';
  if (s.includes('مامون') || s.includes('مأمون')) return 'مامون';
  if (s.includes('بيان')) return 'بيان';
  if (s.includes('فاراب')) return 'فارابي';
  if (s.includes('سلام') && !s.includes('حي السلام')) return 'سلام';
  if (s.includes('ابن سينا')) return 'ابن سينا';
  if (s.includes('حكم')) return 'حكمة';
  if (s.includes('مشرق')) return 'مشرق';
  if (s.includes('مستقبل')) return 'مستقبل';
  if (s.includes('عين')) return 'عين';
  if (s.includes('كتاب')) return 'كتاب';
  if (s.includes('امام كاظم') || s.includes('الامام الكاظم')) return 'امام كاظم';
  if (s.includes('تقني') || s.includes('فنون تطبيقية')) return 'تقنية';
  if (s.includes('جادرية') || s.includes('جامعة بغداد') || s.includes('كلية بغداد') || s.includes('طب بغداد') || s.includes('هندسة بغداد')) return 'بغداد';
  return s.replace(/(كلية|جامعة|معهد|الجامعة|الكلية|المعهد)\s+/g, '').trim();
}

