function cleanLoc(s: string) {
  return (s || '')
    .toLowerCase()
    .replace(/[\u064B-\u065F]/g, '')
    .replace(/^(منطقة|حي|شارع|مجمع)\s+/, '')
    .replace(/^ال/, '')
    .replace(/[ةه]$/, '')
    .replace(/[ىي]$/, '')
    .replace(/(.)\1+/g, '$1')
    .trim();
}

function isSingleLocationMatch(userLoc: string, adLoc: string): boolean {
  if (!userLoc || !adLoc) return false;
  const u = cleanLoc(userLoc);
  const a = cleanLoc(adLoc);
  if (!u || !a) return false;
  
  if (a.includes(u) || u.includes(a)) return true;
  
  if (u.length >= 3 && a.length >= 3) {
    let matches = 0;
    for (let i = 0; i < u.length - 1; i++) {
      const bigram = u.substring(i, i + 2);
      if (a.includes(bigram)) matches++;
    }
    const score = (2.0 * matches) / (u.length - 1 + a.length - 1);
    if (score >= 0.45) return true;
  }
  return false;
}

function isLocationMatch(userLoc: string, adLoc: string): boolean {
  if (!userLoc || !adLoc) return false;
  const parts = userLoc.split(/[,،\/\|\+]+|\s+و\s+/).map(p => p.trim()).filter(Boolean);
  if (parts.length > 1) {
    return parts.some(p => isSingleLocationMatch(p, adLoc));
  }
  return isSingleLocationMatch(userLoc, adLoc);
}

function normArabic(s: string): string {
  return (s || '').toLowerCase()
    .replace(/[إأآا]/g, 'ا')
    .replace(/[ةه]/g, 'ه')
    .replace(/[ىي]/g, 'ي')
    .replace(/[ؤئ]/g, 'ء')
    .replace(/[\u064B-\u065F]/g, '')
    .trim();
}

