function searchIraqiInstitutions(query: string): IraqiAcademicInstitution[] {
  if (!query || query.trim().length === 0) return [];
  const cleanQ = normArabic(query)
    .replace(/^(كليه|جامعه|معهد|الجامعه|الكليه|المعهد|دائره|وزاره|مستشفي|مستشفى|شركه|لـكليه|لـجامعه|لكليه|لجامعه)\s+/, '')
    .trim();

  const queryTerms = cleanQ.split(/\s+/).filter(t => t.length >= 2);
  const qNorm = normArabic(query);

  const scored: { inst: IraqiAcademicInstitution; score: number }[] = [];

  for (const inst of IRAQI_UNIVERSITIES) {
    let score = 0;
    const instNameNorm = normArabic(inst.name);
    
    // Direct matches in official name
    if (instNameNorm === qNorm || instNameNorm === cleanQ) {
      score += 150;
    } else if (instNameNorm.includes(cleanQ)) {
      score += 100;
    } else if (cleanQ.includes(instNameNorm)) {
      score += 80;
    }

    // Check aliases and keywords
    for (const kw of inst.keywords) {
      const kwNorm = normArabic(kw);
      if (kwNorm === qNorm || kwNorm === cleanQ) {
        score += 120;
      } else if (kwNorm.includes(cleanQ) || cleanQ.includes(kwNorm)) {
        score += 70;
      } else if (queryTerms.some(t => kwNorm.includes(t))) {
        score += 30;
      }
    }

    if (score > 0) {
      scored.push({ inst, score });
    }
  }

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, 6).map(s => s.inst);
}

function renderUniversityScopeKeyboard(activeCategory = 'pvt_bg', pageNum = 0) {
  const catTitles: { [k: string]: string } = {
    pvt_bg: '🎓 كليات وجامعات بغداد الأهلية',
    gov_bg: '🏛️ جامعات بغداد الحكومية والمعاهد',
    south: '🕌 جامعات الفرات الأوسط والجنوب',
    north: '🌄 جامعات المحافظات الشمالية والغربية',
    org_gov: '🏢 وزارات ومؤسسات وشركات كبرى'
  };

  const PAGE_SIZE = 8;
  const filtered = IRAQI_UNIVERSITIES.filter(u => u.category === activeCategory);
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE) || 1;
  const page = Math.max(0, Math.min(pageNum, totalPages - 1));
  const pageItems = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const inline_keyboard: any[][] = [];

  // Top search bar button
  inline_keyboard.push([
    { text: '🔍 بحث سريع بالاسم (جامعات / كليات / دوائر)', callback_data: 'partner_trans_search_prompt' }
  ]);

  for (let i = 0; i < pageItems.length; i += 2) {
    const row = [];
    row.push({
      text: pageItems[i].name,
      callback_data: `partner_sel_${pageItems[i].id}`
    });
    if (i + 1 < pageItems.length) {
      row.push({
        text: pageItems[i + 1].name,
        callback_data: `partner_sel_${pageItems[i + 1].id}`
      });
    }
    inline_keyboard.push(row);
  }

  // Navigation pagination bar
  const navRow: any[] = [];
  if (page > 0) {
    navRow.push({ text: '⬅️ السابق', callback_data: `partner_uni_p_${activeCategory}_${page - 1}` });
  }
  navRow.push({ text: `📄 صفحة ${page + 1} من ${totalPages}`, callback_data: `partner_uni_p_${activeCategory}_${page}` });
  if (page < totalPages - 1) {
    navRow.push({ text: 'التالي ➡️', callback_data: `partner_uni_p_${activeCategory}_${page + 1}` });
  }
  inline_keyboard.push(navRow);

  // Category Selector Tabs
  inline_keyboard.push([
    { text: activeCategory === 'pvt_bg' ? '🔘 🎓 أهلي بغداد' : '🎓 أهلي بغداد', callback_data: 'partner_uni_p_pvt_bg_0' },
    { text: activeCategory === 'gov_bg' ? '🔘 🏛️ حكومي بغداد' : '🏛️ حكومي بغداد', callback_data: 'partner_uni_p_gov_bg_0' }
  ]);
  inline_keyboard.push([
    { text: activeCategory === 'south' ? '🔘 🕌 الفرات والجنوب' : '🕌 الفرات والجنوب', callback_data: 'partner_uni_p_south_0' },
    { text: activeCategory === 'north' ? '🔘 🌄 الشمال والغربية' : '🌄 الشمال والغربية', callback_data: 'partner_uni_p_north_0' }
  ]);
  inline_keyboard.push([
    { text: activeCategory === 'org_gov' ? '🔘 🏢 وزارات ومؤسسات' : '🏢 وزارات ومؤسسات', callback_data: 'partner_uni_p_org_gov_0' }
  ]);

  // Fallback / Custom / Cancel options
  inline_keyboard.push([
    { text: '🌐 كل الجامعات (عام)', callback_data: 'partner_trans_kw_all' },
    { text: '✏️ كتابة اسم مخصص', callback_data: 'partner_trans_kw_custom' }
  ]);
  inline_keyboard.push([
    { text: '❌ إلغاء', callback_data: 'cancel_wizard' }
  ]);

  const text = 
    `🚌 <b>تحديد نطاق خطوط النقل لقناتك:</b>\n\n` +
    `📍 <b>القسم المختار:</b> <b>${catTitles[activeCategory] || activeCategory}</b>\n\n` +
    `اختر كليتك أو مؤسستك مباشرة للربط المعتمد غير القابل للخطأ 🎯\n` +
    `<i>(يمكنك استخدام زر 🔍 البحث بالاسم، أو أزرار السابق والتالي ⬅️ ➡️)</i>`;

  return { text, markup: { inline_keyboard } };
}

function buildTransportCard(
  lines: any[], 
  pageIndex: number, 
  fromName: string, 
  origin: string, 
  destination: string, 
  isGroup = false,
  reqId = ''
) {
  const total = lines.length;
  const idx = Math.max(0, Math.min(pageIndex, total - 1));
  const l = lines[idx];
  const fareText = formatTgPrice(l.price);
  const seatsCount = l.available_seats !== undefined && l.available_seats !== null ? l.available_seats : 4;
  const ratingAvg = l.rating_avg || 5.0;
  const trustBadge = ratingAvg >= 4.5 ? `⭐ ${ratingAvg} | 🎖️ كابتن موثوق` : `⭐ ${ratingAvg}`;
  const seatsText = seatsCount === 1 ? '🔥 مقعد أخير متبقي!' : (seatsCount > 0 ? `${seatsCount} مقاعد شاغرة` : '🔒 الخط مكتمل');
  
  const descPhoneMatch = (l.description || '').match(/(?:07[3-9]\d{8}|\+9647[3-9]\d{8}|07\d{2}\s?\d{3}\s?\d{4})/);
  const rawPhone = l.phone || (descPhoneMatch ? descPhoneMatch[0] : '');
  const cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
  let waPhone = cleanPhone.startsWith('07') ? '964' + cleanPhone.substring(1) : cleanPhone.replace('+', '');

  let cleanDetails = '';
  if (l.description) {
    try {
      const rawDesc = String(l.description).trim();
      if (rawDesc.startsWith('{') && rawDesc.endsWith('}')) {
        const d = JSON.parse(rawDesc);
        const parts = [];
        if (d.targetAudience) parts.push(`👥 ${d.targetAudience}`);
        if (d.shift) parts.push(`⏰ ${d.shift}`);
        if (d.vehicleType) parts.push(`🚗 ${d.vehicleType} (${d.seats || 4} مقاعد)`);
        if (d.note) parts.push(`📝 ${d.note}`);
        cleanDetails = parts.join(' | ');
      } else {
        cleanDetails = rawDesc.substring(0, 120);
      }
    } catch(e) {
      cleanDetails = String(l.description).substring(0, 120);
    }
  }

  let cardText = '';
  const inlineButtons: any[][] = [];

  const targetIdKey = reqId || 'route';
  const prevCb = `tpage_${targetIdKey}_${idx - 1}`;
  const nextCb = `tpage_${targetIdKey}_${idx + 1}`;

  if (isGroup) {
    // 📱 ULTRA-COMPACT MINI CARD FOR PUBLIC GROUPS (صغيرة ومختصرة جداً لمنع الفوضى بكروب)
    cardText = 
      `🚌 <b>يا هلا ${fromName} 🌹 مسار مقترح متوفر:</b>\n` +
      `📍 <b>المسار:</b> ${l.location || origin || 'بغداد'} ⬅️ ${l.city || destination || 'الجامعة'}\n` +
      `💺 <b>المقاعد:</b> ${seatsText} | 🎖️ ${trustBadge}\n` +
      `💰 <b>الأجرة:</b> ${fareText}` + (cleanPhone ? ` | 📞 <code>${cleanPhone}</code>` : '') + `\n\n` +
      `⚠️ <i>ملاحظة: هذه المجموعة للطلاب الي يحتاجون خطوط أو يريدون يسوون خطوط لتسهيل أمرهم. نحن غير مسؤولين عن أصحاب الخطوط أو عن الطلاب، وبالتوفيق للجميع 🌹</i>\n\n` +
      `<i>اضغط أدناه لحجز مقعدك والتواصل بالخاص 🔒</i>`;

    // Row 1: Primary Private Booking Deep-Link Button
    inlineButtons.push([
      { text: '📩 حجز مقعد ومتابعة التفاصيل بالخاص 🌹', url: `https://t.me/${BOT_USERNAME}?start=book_${l.id}` }
    ]);

    // Row 2: WhatsApp direct if available
    const commRow: any[] = [];
    if (waPhone) {
      const prefill = encodeURIComponent('السلام عليكم كابتن، شفت خطك بسوق بغداد وحابة استفسر عن حجز مقعد');
      commRow.push({ text: '💬 تواصل واتساب 🟢', url: `https://wa.me/${waPhone}?text=${prefill}` });
    }
    if (commRow.length > 0) inlineButtons.push(commRow);

    // Row 3: Pagination if multiple lines
    if (total > 1) {
      const navRow: any[] = [];
      if (idx > 0) {
        navRow.push({ text: '⬅️ السابق', callback_data: prevCb });
      }
      navRow.push({ text: `📄 [ ${idx + 1} / ${total} ]`, callback_data: 'noop_page' });
      if (idx < total - 1) {
        navRow.push({ text: 'التالي ➡️', callback_data: nextCb });
      }
      inlineButtons.push(navRow);
    }

    // Row 4: Resolution & Delete on demand
    inlineButtons.push([
      { text: '🛑 لكيت خط خلاص', callback_data: `matched_req_direct_${cleanPhone || 'ok'}` },
      { text: '🗑️ حذف هذا الرد', callback_data: 'del_group_msg' }
    ]);
    inlineButtons.push([
      { text: '🚌 باقي الخطوط بالموقع', url: 'https://www.souqbaghdad.store/transport' }
    ]);

  } else {
    // 💬 RICH DETAILED CARD FOR PRIVATE CHAT (بخاص نفسها بتفاصيل كاملة)
    const isAllMode = targetIdKey.startsWith('all');
    cardText = 
      (isAllMode 
        ? `🚌 <b>يا هلا بيك ${fromName}! 🌹 تصفح كافة خطوط بغداد العامة (${total}):</b>\n\n`
        : `🚌 <b>يا هلا بيك ${fromName}! 🌹 وجدنا لك (${total}) خطوط متوفرة لمسارك:</b>\n\n`) +
      `━━━━━━━━━━━━━━━━━━\n` +
      `🏷️ <b>الخط [${idx + 1} من ${total}]: ${l.title}</b> [🟢 نشط]\n` +
      `🎖️ <b>تقييم الكابتن:</b> <b>${trustBadge}</b>\n` +
      `💺 <b>المقاعد الشاغرة:</b> <b>${seatsText}</b>\n` +
      `📍 <b>المناطق:</b> ${l.location || origin || 'بغداد'}` +
      (l.pickup_lat && l.pickup_lng 
        ? `\n   └ 📍 <a href="https://www.google.com/maps/search/?api=1&query=${l.pickup_lat},${l.pickup_lng}">خرائط Google</a> | <a href="https://waze.com/ul?ll=${l.pickup_lat},${l.pickup_lng}&navigate=yes">تطبيق Waze</a>` 
        : '') + `\n` +
      `🏢 <b>الوجهة:</b> ${l.city || destination || 'الجامعة'}\n` +
      `💰 <b>الأجرة:</b> ${fareText}\n` +
      (cleanPhone ? `📞 <b>هاتف الكابتن:</b> <code>${cleanPhone}</code>\n` : '') +
      (cleanDetails ? `📝 <b>التفاصيل:</b> ${cleanDetails}\n` : '') +
      `━━━━━━━━━━━━━━━━━━\n` +
      `⚠️ <b>تنبيه وشروط الاستخدام:</b>\n` +
      `هذه الخدمة مخصصة للطلاب الي يحتاجون خطوط أو يريدون يسوون خطوط لتسهيل أمرهم.\n` +
      `📌 <b>ملاحظة:</b> نحن غير مسؤولين عن أصحاب الخطوط أو عن الطلاب.\n` +
      `وبالتوفيق للجميع 🌹\n` +
      `━━━━━━━━━━━━━━━━━━\n\n` +
      `💡 <i>تصفحي الخطوط بالأزرار أدناه (السابق / التالي) وتواصلي مباشرة مع الكابتن المناسب:</i>`;

    // Row 1: 1-Click Direct Request to Captain
    inlineButtons.push([{ text: '📩 إرسال طلب حجز مقعد للكابتن ⚡', callback_data: `req_seat_${l.id}` }]);

    // Location Map Button if available
    if (l.pickup_lat && l.pickup_lng) {
      const gLink = `https://www.google.com/maps/search/?api=1&query=${l.pickup_lat},${l.pickup_lng}`;
      const wLink = `https://waze.com/ul?ll=${l.pickup_lat},${l.pickup_lng}&navigate=yes`;
      inlineButtons.push([
        { text: '🚙 فتح في تطبيق Waze 🚗', url: wLink },
        { text: '📍 خرائط Google', url: gLink }
      ]);
    }

    // Row 2: WhatsApp direct chat
    const commRow: any[] = [];
    if (waPhone || cleanPhone) {
      const p = waPhone || cleanPhone;
      const prefill = encodeURIComponent('السلام عليكم كابتن، شفت خطك بسوق بغداد وحابة استفسر عن حجز مقعد');
      commRow.push({ text: '💬 تواصل واتساب مع الكابتن 🟢', url: `https://wa.me/${p}?text=${prefill}` });
    }
    if (commRow.length > 0) inlineButtons.push(commRow);

    // Row 3: Pagination Navigation (السابق / التالي)
    if (total > 1) {
      const navRow: any[] = [];
      if (idx > 0) {
        navRow.push({ text: '⬅️ السابق', callback_data: prevCb });
      }
      navRow.push({ text: `📄 [ ${idx + 1} / ${total} ]`, callback_data: 'noop_page' });
      if (idx < total - 1) {
        navRow.push({ text: 'التالي ➡️', callback_data: nextCb });
      }
      inlineButtons.push(navRow);
    }

    // Row 4: Mode Switcher (عرض الكل vs حسب الطلب والمسار)
    if (isAllMode) {
      const returnTarget = targetIdKey.includes(':') ? targetIdKey.split(':')[1] : 'route';
      inlineButtons.push([
        { text: `🎯 عرض الخطوط حسب طلبي ومساري (${origin || 'منطقتي'})`, callback_data: `tpage_${returnTarget}_0` }
      ]);
    } else {
      const allTarget = targetIdKey && targetIdKey !== 'route' ? `all:${targetIdKey}` : 'all';
      inlineButtons.push([
        { text: '🌐 تصفح كافة خطوط بغداد (عرض الكل)', callback_data: `tpage_${allTarget}_0` }
      ]);
    }

    // Row 5: My Routes & Resolution
    inlineButtons.push([
      { text: '📋 مساراتي وتنبيهاتي', callback_data: 'manage_my_routes' },
      { text: '🛑 لكيت خط خلاص', callback_data: `matched_req_direct_${cleanPhone || 'ok'}` }
    ]);

    // Row 6: Terms & Disclaimer
    inlineButtons.push([
      { text: '📜 شروط الاستخدام وإخلاء المسؤولية', callback_data: 'terms_transport' }
    ]);

    // Row 7: Main Menu & Explore
    inlineButtons.push([
      { text: '🏠 القائمة الرئيسية', callback_data: 'main_menu' },
      { text: '🚌 تصفح الكل بالموقع', url: 'https://www.souqbaghdad.store/transport' }
    ]);
  }

  return { text: cardText, markup: { inline_keyboard: inlineButtons } };
}

