async function finishRadarRegistration(chatId: string | number, origin: string, destination: string, fromUser: any, supabase: any, callbackMsgId?: number, phone = '') {
  const userTgId = fromUser?.id ? String(fromUser.id) : null;
  const userChatIdStr = String(chatId);
  const fromName = fromUser?.first_name || 'عزيزنا';

  // 1. Save / Deduplicate in transport_requests
  let reqId: string | null = null;
  try {
    const { data: existingReq } = await supabase
      .from('transport_requests')
      .select('id, origin, destination')
      .or(`telegram_chat_id.eq.${userChatIdStr}${userTgId ? `,telegram_user_id.eq.${userTgId}` : ''}`)
      .eq('status', 'pending');

    const match = existingReq?.find((r: any) => 
      isLocationMatch(r.origin, origin) && 
      (!destination || !r.destination || getCoreLocationKeyword(r.destination) === getCoreLocationKeyword(destination))
    );

    if (match) {
      reqId = match.id;
    } else {
      const safeChatId = (userChatIdStr && !userChatIdStr.startsWith('-')) 
        ? userChatIdStr 
        : (userTgId && !userTgId.startsWith('-') ? userTgId : null);

      const reqPayload: any = {
        telegram_chat_id: safeChatId,
        telegram_user_id: (userTgId && !userTgId.startsWith('-')) ? userTgId : null,
        user_name: fromName,
        origin: origin,
        destination: destination,
        raw_query: phone ? `رادار: ${origin} إلى ${destination} | هاتف: ${phone}` : `رادار: ${origin} إلى ${destination}`,
        status: 'pending'
      };
      if (phone) reqPayload.phone = phone;

      const { data: insertedReq } = await supabase.from('transport_requests').insert(reqPayload).select('id').maybeSingle();
      reqId = insertedReq?.id || null;
    }
  } catch(e) {
    console.error('Error in finishRadarRegistration:', e);
  }

  // Save seeker route in state so pagination stays locked to this route
  try {
    await supabase.from('telegram_users').update({
      bot_state: {
        is_subscribed: true,
        seeker_origin: origin,
        seeker_destination: destination,
        last_origin: origin,
        last_dest: destination,
        last_req_id: reqId
      }
    }).eq('telegram_chat_id', chatId);
  } catch(e) {}

  // 2. Check if active driver lines exist right now!
  const { data: activeDrivers } = await supabase
    .from('ads')
    .select('id, short_id, title, location, description, price, phone, user_id, telegram_message_id, image_url, images')
    .eq('status', 'active')
    .or('category.eq.transport,type.eq.transport')
    .limit(100);

  const matchedLines = (activeDrivers || []).filter((ad: any) => {
    const adText = `${ad.title || ''} ${ad.location || ''} ${ad.description || ''}`.toLowerCase();
    const origMatch = isLocationMatch(origin, adText);
    const destMatch = !destination || isLocationMatch(destination, adText) || (getCoreLocationKeyword(destination) ? adText.includes(getCoreLocationKeyword(destination)) : false);
    return origMatch && destMatch;
  });

  if (matchedLines.length > 0) {
    const noticeText = 
      `🎉 <b>تم تفعيل رادار الخطوط لمسارك بنجاح! 🚌✨</b>\n\n` +
      `📍 <b>منطقة الانطلاق:</b> <b>${origin}</b>\n` +
      `🏢 <b>الوجهة:</b> <b>${destination}</b>\n` +
      `📡 <b>حالة الرادار:</b> نشط ويعمل على مدار الساعة 24/7\n\n` +
      `🔥 <b>ولحسن الحظ، وجدنا لك (${matchedLines.length}) خطوط متوفرة حالياً لمسارك! تصفحها أدناه:</b>`;

    const noticeBtns = [
      [{ text: '📋 مساراتي وتنبيهاتي', callback_data: 'manage_my_routes' }],
      [{ text: '➕ تسجيل مسار إضافي 🔔', callback_data: 'start_route_radar' }]
    ];

    if (callbackMsgId) {
      try {
        await editMessageText(chatId, callbackMsgId, noticeText, { inline_keyboard: noticeBtns });
      } catch(e) {
        await sendMessage(chatId, noticeText, { inline_keyboard: noticeBtns });
      }
    } else {
      await sendMessage(chatId, noticeText, { inline_keyboard: noticeBtns });
    }
    const card = buildTransportCard(matchedLines, 0, fromName, origin, destination, false, reqId || 'route');
    await sendMessage(chatId, card.text, card.markup);
  } else {
    const confirmMsg = 
      `🎉 <b>تم تفعيل رادار الخطوط لمسارك بنجاح! 🚌✨</b>\n\n` +
      `📍 <b>منطقة الانطلاق:</b> <b>${origin}</b>\n` +
      `🏢 <b>الوجهة:</b> <b>${destination}</b>\n` +
      `📡 <b>حالة الرادار:</b> نشط ويعمل على مدار الساعة 24/7\n\n` +
      `🔔 <b>شكراً لك!</b> أول ما ينشر أي كابتن خطاً يمر بمنطقتك، سنرسل لك إشعاراً فورياً على الخاص مع رقم الكابتن وزر الحجز المباشر ⚡\n\n` +
      `💡 <i>يمكنك في أي وقت إيقاف التنبيهات أو حذف المسار من زر «مساراتي المسجلة».</i>`;

    const confirmBtns = [
      [{ text: '📢 نشر طلبي في قناة التلغرام أيضاً 🚀', callback_data: `publish_radar_channel_${reqId || 'user'}` }],
      [{ text: '🛑 إيقاف التنبيهات لهذا المسار', callback_data: `del_route_req_${reqId || 'user'}` }],
      [{ text: '📋 مساراتي المسجلة للإشعارات', callback_data: 'manage_my_routes' }],
      [{ text: '➕ تسجيل مسار إضافي 🔔', callback_data: 'start_route_radar' }],
      [{ text: '🏠 القائمة الرئيسية', callback_data: 'main_menu' }]
    ];

    if (callbackMsgId) {
      try {
        const editRes = await editMessageText(chatId, callbackMsgId, confirmMsg, { inline_keyboard: confirmBtns });
        if (editRes?.ok) return editRes;
      } catch(e) {}
    }
    await sendMessage(chatId, confirmMsg, { inline_keyboard: confirmBtns });
  }
}

async function notifyDriverOfWaitingPassengers(driverChatId: string | number, driverName: string, regions: string, destination: string, supabase: any, driverPhone?: string) {
  try {
    const { data: waitingStudents } = await supabase
      .from('transport_requests')
      .select('*')
      .eq('status', 'pending')
      .order('created_at', { ascending: false })
      .limit(30);

    if (!waitingStudents || waitingStudents.length === 0) return;

    const regLower = (regions || '').toLowerCase();
    const destCore = getCoreLocationKeyword(destination);

    const matched = waitingStudents.filter((st: any) => {
      const stOrig = (st.origin || '').toLowerCase().trim();
      const stDestCore = getCoreLocationKeyword(st.destination || '');
      if (!stOrig) return false;
      const originMatch = regLower.includes(stOrig) || stOrig.split(/\s+/).some((w: string) => w.length > 2 && regLower.includes(w));
      const destMatch = !destCore || !stDestCore || destCore === stDestCore || (st.destination || '').toLowerCase().includes(destCore);
      return originMatch && destMatch;
    }).slice(0, 5);

    if (matched.length === 0) return;

    let driverMsg = `🎯 <b>يا هلا كابتن ${driverName}! 🌹</b>\n` +
      `وجدنا لك <b>(${matched.length})</b> طلبات ركاب وطلاب يبحثون عن خط بنفس مسارك حالياً:\n\n`;

    const buttons: any[][] = [];
    const cleanPhone = (driverPhone || '').replace(/[^0-9]/g, '');

    for (let i = 0; i < matched.length; i++) {
      const st = matched[i];
      driverMsg += `<b>${i + 1}. الراكب: ${st.user_name || 'طالب'}</b>\n` +
        `📍 <b>المسار:</b> ${st.origin} ⬅️ ${st.destination || 'الجامعة'}\n` +
        (st.raw_query ? `💬 <b>نص الطلب:</b> <i>«${st.raw_query}»</i>\n` : '') +
        `\n`;

      const row: any[] = [];
      if (st.telegram_chat_id) {
        row.push({ text: `💬 مراسلة الراكب (${i + 1}) 🌹`, url: `tg://user?id=${st.telegram_chat_id}` });
      }
      row.push({ text: `📢 إبلاغ الراكب بتوفر خطك (${i + 1}) ⚡`, callback_data: `alert_p_${st.id}_${cleanPhone || 'nophone'}` });
      buttons.push(row);
    }

    driverMsg += `💡 <i>اضغط على «📢 إبلاغ الراكب» لإرسال بطاقة خطك ورقمك إلى خاص الراكب فوراً ✨</i>`;
    buttons.push([{ text: '🚌 تصفح جميع طلبات الركاب بالموقع', url: 'https://www.souqbaghdad.store/transport' }]);

    await sendMessage(driverChatId, driverMsg, { inline_keyboard: buttons });
  } catch (err) {
    console.error('Error notifying driver of waiting passengers:', err);
  }
}

async function handleSmartTransportSearch(chatId: string | number, rawText: string, fromUser: any, supabase: any, isGroup = false, userMessageId?: number | string) {
  // 1. Normalize Iraqi Arabic and common typos
  function replaceAr(text: string, searchWords: string, replacement: string) {
    return text.replace(new RegExp(`(?<![\\u0600-\\u06FF])(${searchWords})(?![\\u0600-\\u06FF])`, 'gi'), replacement);
  }

  // 0. Remove redundant repeated letters (e.g. راااافدين -> رافدين, جمييييلة -> جميلة)
  let norm = rawText.replace(/[\\\/](line|lines|خط|خطوط)/gi, '').replace(/(.)\1{2,}/g, '$1$1');
  norm = replaceAr(norm, 'خك|حط|خظ|خيط|خـط|خطط', 'خط');
  norm = replaceAr(norm, 'سيايق|سياق|سايقق|سواق', 'سايق');
  norm = replaceAr(norm, 'اربد|اريدد|ادورر|ابحثث|محتاجج|محتاجه', 'محتاج');
  norm = replaceAr(norm, 'جميله|جميلهه|جميلةة|جميلية', 'جميلة');
  norm = replaceAr(norm, 'الرفدين|الرافين|رافدين|لرافدين|للرافدين|الرافيدين|كليه الرافدين|جامعة الرافدين|جامعه الرافدين|معهد الرافدين', 'كلية الرافدين');
  norm = replaceAr(norm, 'المستنصريه|مستنصريه|للمستنصرية|مستنصرية|المستنصرية', 'الجامعة المستنصرية');
  norm = replaceAr(norm, 'التكنولوجيه|تكنولوجيه|تكنلوجيا|التكنلوجيا|تكنلوجيه|التكنلوجية|تكنولوجية|التكنولوجية|تكنلوجي|تكنولوجي|شارع الصناعة|صناعة|الصناعة', 'الجامعة التكنولوجية');
  norm = replaceAr(norm, 'الاسراء|للاسراء|إسراء|اسراء|الإسراء|كليه الاسراء|جامعة الاسراء', 'كلية الاسراء');
  norm = replaceAr(norm, 'اوروك|أوروك|لأوروك|لاوروك|جامعة اوروك', 'جامعة اوروك');
  norm = replaceAr(norm, 'الفراهيدي|فراهيدي|للفراهيدي|جامعة الفراهيدي', 'جامعة الفراهيدي');
  norm = replaceAr(norm, 'دجله|دجلة|لدجلة|لدجله|كلية دجلة|جامعة دجلة', 'جامعة دجلة');
  norm = replaceAr(norm, 'التراث|تراث|للتراث|كلية التراث|جامعة التراث', 'كلية التراث');
  norm = replaceAr(norm, 'الرشيد|رشيد|للرشيد|كلية الرشيد', 'كلية الرشيد');
  norm = replaceAr(norm, 'المعارف|معارف|للمعارف|جامعة المعارف', 'كلية المعارف');
  norm = replaceAr(norm, 'المامون|المأمون|مامون|مأمون|كلية المامون|كلية المأمون', 'كلية المأمون');
  norm = replaceAr(norm, 'البيان|بيان|جامعة البيان', 'جامعة البيان');
  norm = replaceAr(norm, 'الفارابي|فارابي|كلية الفارابي', 'كلية الفارابي');
  norm = replaceAr(norm, 'سيديه|سيدية', 'السيدية');
  norm = replaceAr(norm, 'دوره|الدوره', 'الدورة');
  norm = replaceAr(norm, 'جامعه|الجامعه', 'جامعة');
  norm = replaceAr(norm, 'كليه|الكليه', 'كلية');
  norm = replaceAr(norm, 'شعله|الشعله', 'الشعلة');
  norm = replaceAr(norm, 'حريه|الحريه', 'الحرية');
  norm = replaceAr(norm, 'غزاليه|الغزاليه', 'الغزالية');
  norm = replaceAr(norm, 'منصور|المنصورر', 'المنصور');
  norm = replaceAr(norm, 'بنوك|البنوكك', 'البنوك');
  norm = replaceAr(norm, 'شعب|الشعبب', 'الشعب');
  norm = replaceAr(norm, 'كراده|الكراده|كرادة داخل|كرادة خارج', 'الكرادة');
  norm = replaceAr(norm, 'زعفرانيه|الزعفرانيه', 'الزعفرانية');
  norm = replaceAr(norm, 'كاظميه|الكاظميه', 'الكاظمية');
  norm = replaceAr(norm, 'اعظميه|الاعظميه', 'الأعظمية');
  norm = replaceAr(norm, 'طالبيه|طالبية|الطالبيه', 'الطالبية');
  norm = replaceAr(norm, 'سومر|حي سومر', 'حي سومر');
  norm = replaceAr(norm, 'معلمين|حي المعلمين', 'حي المعلمين');
  norm = replaceAr(norm, 'مهندسين|المهندسين|حي المهندسين|مهدسين|المهدسين|حي المهدسين|مهنسين|المهنسين', 'المهندسين');
  norm = replaceAr(norm, 'عامريه|العامريه|عامرية', 'العامرية');
  norm = replaceAr(norm, 'حارثيه|الحارثيه|حارثية', 'الحارثية');
  norm = replaceAr(norm, 'قادسيه|القادسيه|قادسية', 'القادسية');
  norm = replaceAr(norm, 'امين|الامين', 'الأمين');
  norm = norm.trim();

  const lowerRaw = rawText.toLowerCase();

  let rawFirstName = fromUser?.first_name || '';
  // Clean special characters, emojis, symbols, and take the first clean word
  let cleanFirstWord = rawFirstName.replace(/[^\p{L}\p{N}\s]/gu, '').trim().split(/\s+/)[0] || '';
  let fromName = cleanFirstWord || fromUser?.first_name || 'عزيزنا';
  let contactHandle = fromUser?.username ? `@${fromUser.username}` : fromName;
  if (fromUser?.username) {
    const u = fromUser.username.toLowerCase();
    if (u.includes('anonymous') || u.includes('bot')) {
      fromName = 'عزيزنا';
      contactHandle = 'الكروب';
    }
  }

  const isOwnerUser = 
    String(fromUser?.id) === '777557036' || 
    String(fromUser?.id) === '6474465462' || 
    String(fromUser?.id) === '7083049103' || 
    String(fromUser?.id) === '108892492' ||
    fromUser?.username === 'nooraldeinsbah' ||
    fromUser?.username === 'nhuguyg' ||
    fromUser?.username === 'nooraldein';

  if (isOwnerUser) {
    fromName = 'مديرنا ومؤسس المنصة الغالي 👑';
  }

  // Extract Iraqi phone number if present
  const phoneMatch = rawText.match(/(?:07[3-9]\d{8}|\+9647[3-9]\d{8}|07\d{2}\s?\d{3}\s?\d{4})/);
  const extractedPhone = phoneMatch ? phoneMatch[0].replace(/\s+/g, '') : null;

  // Extract mention username if present (e.g. @mdzn21)
  const mentionMatch = rawText.match(/@[a-zA-Z0-9_]{4,}/);
  if (mentionMatch) {
    contactHandle = mentionMatch[0];
  }

  // --------------------------------------------------------------------------
  // 🚗 CASE 1: DRIVER / LINE PROVIDER (صاحب خط / سائق يعرض خطه ومقاعده)
  // --------------------------------------------------------------------------
  const isSeekerExplicit = 
    lowerRaw.includes('محتاج') || lowerRaw.includes('محتاجة') || lowerRaw.includes('محتاجه') || lowerRaw.includes('محتاجين') || 
    lowerRaw.includes('اريد') || lowerRaw.includes('أريد') || lowerRaw.includes('نريد') || 
    lowerRaw.includes('رايد') || lowerRaw.includes('رايده') || lowerRaw.includes('رايدة') || lowerRaw.includes('رايدين') ||
    lowerRaw.includes('ادور') || lowerRaw.includes('أدور') || lowerRaw.includes('ندور') || 
    lowerRaw.includes('ابحث') || lowerRaw.includes('أبحث') || lowerRaw.includes('نبحث') ||
    lowerRaw.includes('طالبة') || lowerRaw.includes('طالبه') || lowerRaw.includes('طالب') ||
    lowerRaw.includes('راكب') || lowerRaw.includes('عبرية') || lowerRaw.includes('عبريه') ||
    lowerRaw.includes('عفيه') || lowerRaw.includes('عفية') ||
    lowerRaw.includes('ماكو خط') || lowerRaw.includes('اكو خط') || lowerRaw.includes('أكو خط') || lowerRaw.includes('هل يوجد خط');

  const isDriverKeywords = 
    lowerRaw.includes('يتوفر خط') || lowerRaw.includes('متوفر خط') || lowerRaw.includes('يوجد خط') || 
    lowerRaw.includes('اوفر خط') || lowerRaw.includes('أوفر خط') || lowerRaw.includes('عندي خط') || 
    lowerRaw.includes('خط متوفر') || lowerRaw.includes('متوفر مقاعد') || lowerRaw.includes('يوجد مقاعد') || 
    lowerRaw.includes('شاغر') || lowerRaw.includes('مقاعد شاغرة') || lowerRaw.includes('خط صباحي') || 
    lowerRaw.includes('خط مسائي') || lowerRaw.includes('نوع السياره') || lowerRaw.includes('نوع السيارة') || 
    lowerRaw.includes('ستاركس') || lowerRaw.includes('كوستر') || lowerRaw.includes('كيا') || 
    lowerRaw.includes('اوبترا') || lowerRaw.includes('أوبترا') || lowerRaw.includes('النترا') || 
    lowerRaw.includes('توسان') || lowerRaw.includes('طيبة') || lowerRaw.includes('سايبا') ||
    lowerRaw.includes('يمر من المناطق') || lowerRaw.includes('يمر بـ') || lowerRaw.includes('يمر في') ||
    lowerRaw.includes('المناطق المجاوره') || lowerRaw.includes('المناطق المجاورة') ||
    lowerRaw.includes('الاستفسار اكثر') || lowerRaw.includes('الاستفسار أكثر') || lowerRaw.includes('للحجز والاستفسار') ||
    lowerRaw.includes('للحجز') || lowerRaw.includes('للاستفسار') || lowerRaw.includes('متواجد على تلي') ||
    (lowerRaw.includes('خط') && (lowerRaw.includes('تبريد') || lowerRaw.includes('تدفئة') || lowerRaw.includes('انترنت') || lowerRaw.includes('واي فاي')));

  const isDriverRoutePattern = /خط\s+من\s+/i.test(lowerRaw) || /خط\s+.+?\s+(?:إلى|الى|الي|لـ|ل)\s+/i.test(lowerRaw) || /توصيل\s+من\s+/i.test(lowerRaw);

  const isStrongDriver = 
    lowerRaw.includes('يتوفر خط') || lowerRaw.includes('متوفر خط') || lowerRaw.includes('يوجد خط') || 
    lowerRaw.includes('اوفر خط') || lowerRaw.includes('أوفر خط') || lowerRaw.includes('عندي خط') || 
    lowerRaw.includes('خط متوفر') || lowerRaw.includes('متوفر مقاعد') || lowerRaw.includes('يوجد مقاعد') || 
    lowerRaw.includes('عندي سيارة') || lowerRaw.includes('عندي كيا') || lowerRaw.includes('عندي كوستر') || 
    lowerRaw.includes('عندي ستاركس') || lowerRaw.includes('عندي طيبه') || lowerRaw.includes('عندي سايبا') || 
    lowerRaw.includes('سائق خط') || lowerRaw.includes('سايق خط') || lowerRaw.includes('صاحب خط') ||
    lowerRaw.includes('اخذ خط') || lowerRaw.includes('اخذ نفرات') ||
    (isDriverRoutePattern && !isSeekerExplicit);

  // Check if sender is already known as a registered Captain/Driver in DB
  let isSenderDriver = false;
  if (fromUser?.id) {
    try {
      const { data: senderTgUser } = await supabase.from('telegram_users').select('user_role').eq('telegram_chat_id', fromUser.id).maybeSingle();
      if (senderTgUser?.user_role === 'driver') {
        isSenderDriver = true;
      }
    } catch(e) {}
  }

  const isExplicitDriverClaim = 
    lowerRaw.includes('اني كابتن') || lowerRaw.includes('انا كابتن') || 
    lowerRaw.includes('اني سايق') || lowerRaw.includes('انا سايق') || 
    lowerRaw.includes('اني سائق') || lowerRaw.includes('انا سائق') ||
    lowerRaw.includes('صاحب الخط') || lowerRaw.includes('اني صاحب');

  if (isExplicitDriverClaim && fromUser?.id) {
    isSenderDriver = true;
    try {
      await supabase.from('telegram_users').update({ user_role: 'driver' }).eq('telegram_chat_id', fromUser.id);
    } catch(e) {}
  }

  const isAmbiguous = isDriverKeywords && !isStrongDriver && !isSeekerExplicit && !isSenderDriver;
  const isProvider = 
    isSenderDriver || 
    isExplicitDriverClaim || 
    ((isStrongDriver || isDriverKeywords || (isDriverRoutePattern && !isSeekerExplicit)) && !isSeekerExplicit && !isAmbiguous);

  if (isAmbiguous) {
    if (isGroup) return; // In group: stay silent!
    try {
      const { data: tgUser } = await supabase.from('telegram_users').select('*').eq('telegram_chat_id', chatId).maybeSingle();
      let state = tgUser?.bot_state || {};
      state.data = state.data || {};
      state.data.ambig_text = rawText;
      await supabase.from('telegram_users').update({ bot_state: state }).eq('telegram_chat_id', chatId);
    } catch(e) {}

    const askMsg = `👋 <b>يا هلا بيك ${fromName} 🌹</b>\nلم نتمكن من تحديد طلبك بدقة، هل أنت كابتن أم طالب؟`;
    const askMarkup = {
      inline_keyboard: [
        [{ text: '👨‍✈️ أنا كابتن (عندي سيارة / خط)', callback_data: 'ambig_driver' }],
        [{ text: '👨‍🎓 أنا طالب (محتاج خط / راكب)', callback_data: 'ambig_student' }]
      ]
    };
    await sendMessage(chatId, askMsg, askMarkup);
    return;
  }

  if (isProvider) {
    // Check if driver phone is blacklisted / banned
    if (extractedPhone) {
      const { data: isBanned } = await supabase.from('group_warnings').select('user_id').eq('chat_id', 'BANNED_DRIVERS').eq('user_id', extractedPhone).maybeSingle();
      if (isBanned) {
        console.warn(`[BLOCKED DRIVER ATTEMPT] Banned phone ${extractedPhone} tried to post.`);
        return;
      }
    }

    if (isGroup) {
      const driverMsg = 
        `👋 <b>يا هلا بكابتننا العزيز ${fromName} 🚌🌹</b>\n\n` +
        `⚠️ <b>تنبيه هام:</b> رسائل الكروب مخصصة للطلاب والركاب المحتاجين خط فقط.\n` +
        `💡 <b>لتجنب تكرار الإعلان أو الحظر التلقائي بالنظام:</b>\n` +
        `انشر خطك الآن عبر البوت بالخاص مجاناً بضغطة زر 👇 ليصل إعلانك فوراً إلى جميع القنوات والصفحات وتصلك طلبات حجز الطلاب على هاتفك مباشرة! 🚀`;

      const providerMarkup = {
        inline_keyboard: [
          [{ text: '➕ نشر وتثبيت خطي عبر البوت ⚡', url: `https://t.me/${BOT_USERNAME}?start=pubtrans` }],
          [{ text: '📋 إدارة خطوطي النشطة', url: `https://t.me/${BOT_USERNAME}?start=manage_cat_trans` }]
        ]
      };
      await sendOrReplaceGroupMessage(chatId, driverMsg, providerMarkup, supabase, userMessageId);
    } else {
      // 🚗 In Private Chat: Start the 9-step wizard directly so he publishes an official verified line!
      const driverState = {
        step: 'trans_cat',
        data: {
          type: 'offer',
          phone: extractedPhone || null
        }
      };
      await supabase.from('telegram_users').update({ bot_state: driverState }).eq('telegram_chat_id', chatId);

      const driverPrivateMsg = 
        `👋 <b>يا هلا بالسائق العزيز كابتن ${fromName} 🚌✨</b>\n\n` +
        `لتثبيت خطك رسمياً ومطابقته بدقة مع طلبات الركاب ونشره في القنوات والموقع مجاناً:\n` +
        `🚀 <b>ابدأ نشر إعلان خطك الآن (9 خطوات سريعة):</b>\n\n` +
        `👇 <b>الخطوة 2 من 9 — فئة الخط</b>\nالخط مخصص لمن؟ اختر الفئة للمتابعة:`;

      const wizardMarkup = {
        inline_keyboard: [
          [{ text: '🎓 خط طلاب جامعات / كليات', callback_data: 'trans_cat_student' }],
          [{ text: '💼 خط موظفين وشركات', callback_data: 'trans_cat_employee' }],
          [{ text: '🚨 نقل خاص وطارئ / مناسبات', callback_data: 'trans_cat_emergency' }],
          [{ text: '❌ إلغاء النشر', callback_data: 'cancel_wizard' }]
        ]
      };

      await sendMessage(chatId, driverPrivateMsg, wizardMarkup);
    }
    return;
  }

  // --------------------------------------------------------------------------
  // 🎒 CASE 2: STUDENT / LINE SEEKER (طالب / موظف يبحث عن خط)
  // --------------------------------------------------------------------------
  let origin = '';
  let destination = '';

  const INVALID_ORIGIN_PHRASES = [
    'اني مو سايق', 'انا مو سايق', 'مو سايق', 'اني طالب', 'انا طالب', 'طالب', 'طالبة', 
    'محتاج خط', 'محتاجة خط', 'اريد خط', 'ابحث عن خط', 'ادور خط', 'سايق', 'سائق', 'تكسي', 'خط', 'نقل',
    'تلكه خط', 'ينزل خط', 'يجي خط', 'يتوفر خط', 'انشر خط', 'تسجيل خط'
  ];

  const INVALID_ORIGIN_WORDS = [
    'اني', 'انا', 'مو', 'سايق', 'سائق', 'طالب', 'طالبة', 'محتاج', 'محتاجة', 'اريد', 'أريد', 
    'ادور', 'أدور', 'ابحث', 'خط', 'نقل', 'هذا', 'نفسه', 'غير', 'خلاص', 'شكرا', 'تلكه', 'تلقى', 
    'الكه', 'ينزل', 'يجي', 'يصير', 'يتوفر', 'بلغني', 'نبهني', 'اشوف', 'رخصتك', 'فضلك', 'بعد', 
    'اكو', 'كلية', 'جامعة', 'دوام', 'صباحي', 'مسائي', 'انشر', 'تسجيل'
  ];

  function isValidLocation(str: string): boolean {
    if (!str) return false;
    const s = str.trim().toLowerCase();
    if (s.length < 3) return false;
    if (INVALID_ORIGIN_PHRASES.some(p => s === p || s.includes('مو سايق') || s.includes('اني مو') || s.includes('تلكه') || s.includes('بلغني') || s.includes('انشر خط'))) return false;
    const words = s.split(/\s+/);
    const nonStop = words.filter(w => !INVALID_ORIGIN_WORDS.includes(w));
    return nonStop.length > 0;
  }

  const IRAQI_AREAS = [
    'البنوك', 'الشعب', 'المنصور', 'الكرادة', 'الدورة', 'اليرموك', 'الغزالية', 'الزعفرانية', 
    'مدينة الصدر', 'جميلة', 'الأعظمية', 'الاعظمية', 'الكاظمية', 'السيدية', 'الجهاد', 'الحرية', 
    'القاهرة', 'صليخ', 'حي الجامعة', 'الوزيرية', 'حي تونس', 'حي العامل', 'حي الخضراء', 'حي العدل', 
    'حي أور', 'حي اور', 'البياع', 'سبع ابكار', 'الراشدية', 'التاجي', 'المحمودية', 'المدائن', 
    'جسر ديالى', 'حي الاعلام', 'حي الإعلام', 'حي التراث', 'المشتل', 'بغداد الجديدة', 'الغدير', 
    'زيونة', 'شارع فلسطين', 'شارع النضال', 'شارع المغرب', 'باب المعظم', 'باب الشرقي', 'العطيفية', 
    'الوشاش', 'الاسكان', 'المأمون', 'حي حطين', 'الداوودي', 'حي السلام', 'حي الفرات', 'سويب', 
    'ابو دشير', 'أبو دشير', 'الكرخ', 'الرصافة', 'حي البساتين', 'سبع قصور', 'حي دراغ', 'الشرطة الرابعة', 
    'الشرطة الخامسة', 'المسبح', 'عرصات الهندية', 'الكرادة خارج', 'الكرادة داخل', 'البلديات', 'الحبيبية', 
    'الكمالية', 'الفضل', 'الميدان', 'المستنصرية', 'الرافدين', 'جامعة بغداد', 'الجادرية', 'النهرين', 'التكنولوجية',
    'الطالبية', 'طالبية', 'حي سومر', 'الأمين', 'الامين', 'حي المعلمين'
  ];

  // Extract "من [origin] الى/لـ/لل [destination]" accurately (handling attached letters like للجامعة)
  let routeMatch = norm.match(/من\s+(.+?)\s+(?:إلى|الي|الى|لـ|لل|ل|باتجاه)\s*(.+)/i);
  if (routeMatch) {
    const rawOrigin = routeMatch[1].trim().replace(/^(منطقة|حي|شارع)\s+/, '');
    if (isValidLocation(rawOrigin)) {
      origin = rawOrigin;
    }
    destination = routeMatch[2].trim();
  } else {
    routeMatch = norm.match(/(?:إلى|الي|الى|لـ|لل|ل|باتجاه)\s*(.+?)\s+من\s+(.+)/i);
    if (routeMatch) {
      destination = routeMatch[1].trim();
      const rawOrigin = routeMatch[2].trim().replace(/^(منطقة|حي|شارع)\s+/, '');
      if (isValidLocation(rawOrigin)) {
        origin = rawOrigin;
      }
    }
  }

  // If origin not yet found via routeMatch, check IRAQI_AREAS
  if (!origin) {
    for (const a of IRAQI_AREAS) {
      if (norm.toLowerCase().includes(a.toLowerCase())) {
        origin = a;
        break;
      }
    }
  }

  // Parse & resolve destination (colleges & universities) with comprehensive Iraqi alias matching
  const destToCheck = (destination || norm).toLowerCase();
  if (destToCheck.includes('تكنولوج') || destToCheck.includes('تكنلوج') || destToCheck.includes('صناع') || destToCheck.includes('uot')) {
    destination = 'الجامعة التكنولوجية';
  } else if (destToCheck.includes('رافدين') || destToCheck.includes('رفدين') || destToCheck.includes('ruc')) {
    destination = 'كلية الرافدين الجامعة';
  } else if (destToCheck.includes('مستنصر') || destToCheck.includes('مستنصري')) {
    destination = 'الجامعة المستنصرية';
  } else if (destToCheck.includes('نهرين')) {
    destination = 'جامعة النهرين';
  } else if (destToCheck.includes('عراقي')) {
    destination = 'الجامعة العراقية';
  } else if (destToCheck.includes('اسراء') || destToCheck.includes('إسراء')) {
    destination = 'كلية الاسراء الجامعة';
  } else if (destToCheck.includes('اوروك') || destToCheck.includes('أوروك')) {
    destination = 'جامعة اوروك';
  } else if (destToCheck.includes('فراهيد')) {
    destination = 'جامعة الفراهيدي';
  } else if (destToCheck.includes('دجل')) {
    destination = 'جامعة دجلة';
  } else if (destToCheck.includes('تراث')) {
    destination = 'كلية التراث الجامعة';
  } else if (destToCheck.includes('رشيد')) {
    destination = 'كلية الرشيد الجامعة';
  } else if (destToCheck.includes('معارف')) {
    destination = 'جامعة المعارف';
  } else if (destToCheck.includes('مامون') || destToCheck.includes('مأمون')) {
    destination = 'كلية المأمون الجامعة';
  } else if (destToCheck.includes('بيان')) {
    destination = 'جامعة البيان';
  } else if (destToCheck.includes('فاراب')) {
    destination = 'كلية الفارابي الجامعة';
  } else if (destToCheck.includes('سلام') && !destToCheck.includes('حي السلام')) {
    destination = 'كلية السلام الجامعة';
  } else if (destToCheck.includes('ابن سينا')) {
    destination = 'جامعة ابن سينا';
  } else if (destToCheck.includes('حكم')) {
    destination = 'كلية الحكمة الجامعة';
  } else if (destToCheck.includes('مشرق')) {
    destination = 'جامعة المشرق';
  } else if (destToCheck.includes('مستقبل')) {
    destination = 'جامعة المستقبل';
  } else if (destToCheck.includes('عين')) {
    destination = 'جامعة العين';
  } else if (destToCheck.includes('كتاب')) {
    destination = 'جامعة الكتاب';
  } else if (destToCheck.includes('امام كاظم') || destToCheck.includes('الامام الكاظم')) {
    destination = 'كلية الامام الكاظم';
  } else if (destToCheck.includes('تقني') || destToCheck.includes('فنون تطبيقية')) {
    destination = 'الجامعة التقنية الوسطى';
  } else if (destToCheck.includes('بغداد') || destToCheck.includes('جادرية')) {
    destination = 'جامعة بغداد';
  }

  // 1. Fetch strictly ACTIVE driver line offers (exclude completed, sold, matched, or student search ads)
  const { data: allActiveLines } = await supabase
    .from('ads')
    .select('id, short_id, title, location, city, description, price, phone, user_id, telegram_message_id, type, status, category, image_url, images, created_at')
    .eq('category', 'transport')
    .eq('status', 'active')
    .order('created_at', { ascending: false })
    .limit(60);
  
  // Filter for actual driver line offers only (not student requests "ابحث عن خط")
  const activeDriverLines = (allActiveLines || []).filter((ad: any) => {
    const t = (ad.title || '').toLowerCase();
    const isStudentRequest = ad.type === 'request' || t.includes('ابحث') || t.includes('أبحث') || t.includes('محتاج') || t.includes('ادور');
    const isCompleted = ad.status === 'sold' || ad.status === 'matched' || ad.status === 'archived' || ad.status === 'closed';
    return !isStudentRequest && !isCompleted;
  });

  let matchedLines: any[] = [];
  if (activeDriverLines.length > 0) {
    if (origin && destination) {
      // Must match BOTH ORIGIN AND DESTINATION strictly using isDestinationMatch!
      matchedLines = activeDriverLines.filter((ad: any) => {
        const fullAdText = `${ad.title || ''} ${ad.location || ''} ${ad.city || ''} ${ad.description || ''}`.toLowerCase();
        const originMatch = isLocationMatch(origin, fullAdText) || fullAdText.includes(origin.toLowerCase());
        const destMatch = isDestinationMatch(destination, fullAdText, ad.city || '');
        return originMatch && destMatch;
      }).slice(0, 3);
    } else if (origin) {
      // User specified origin only (e.g. محتاج خط من البنوك)
      matchedLines = activeDriverLines.filter((ad: any) => {
        const fullAdText = `${ad.title || ''} ${ad.location || ''} ${ad.city || ''} ${ad.description || ''}`.toLowerCase();
        return isLocationMatch(origin, fullAdText) || fullAdText.includes(origin.toLowerCase());
      }).slice(0, 3);
    }
  }

  const finalOrigin = origin || 'بغداد';
  const finalDestination = destination || 'الجامعة';

  if (origin && (fromUser?.id || chatId)) {
    const targetChatId = fromUser?.id || (isGroup ? null : chatId);
    if (targetChatId) {
      try {
        const { data: u } = await supabase.from('telegram_users').select('bot_state').eq('telegram_chat_id', targetChatId).maybeSingle();
        const s = u?.bot_state || {};
        s.last_origin = finalOrigin;
        s.last_dest = finalDestination;
        if (matchedLines && matchedLines.length > 0) {
          s.last_driver_phone = matchedLines[0].phone || '';
        }
        await supabase.from('telegram_users').update({ bot_state: s }).eq('telegram_chat_id', targetChatId);
      } catch(e) {}
    }
  }

  // If matched active driver lines found -> return them & register seeker for future alerts
  if (matchedLines && matchedLines.length > 0) {
    // 🔔 Always register the seeker in transport_requests for radar notifications of new drivers (strictly in private DM)!
    try {
      await supabase.from('transport_requests').insert({
        telegram_chat_id: isGroup ? null : String(chatId),
        telegram_user_id: fromUser?.id ? String(fromUser.id) : null,
        user_name: fromName,
        origin: finalOrigin,
        destination: finalDestination,
        raw_query: rawText,
        status: 'pending'
      });
    } catch(e) {}

    // Store matched lines & metadata in bot state so in-place pagination works smoothly
    if (chatId) {
      try {
        const { data: u } = await supabase.from('telegram_users').select('bot_state').eq('telegram_chat_id', chatId).maybeSingle();
        const s = u?.bot_state || {};
        s.matched_lines = matchedLines.map((ad: any) => ({
          id: ad.id,
          title: ad.title,
          location: ad.location,
          city: ad.city,
          price: ad.price,
          phone: ad.phone,
          description: ad.description
        }));
        s.seeker_name = fromName;
        s.seeker_origin = finalOrigin;
        s.seeker_destination = finalDestination;
        await supabase.from('telegram_users').update({ bot_state: s }).eq('telegram_chat_id', chatId);
      } catch(e) {}
    }

    if (isGroup) {
      const userMention = fromUser?.username ? `@${fromUser.username}` : (fromName || 'عزيزنا');
      const routeParam = `route_${encodeURIComponent(finalOrigin)}_${encodeURIComponent(finalDestination)}`;
      const routeLink = `https://t.me/${BOT_USERNAME}?start=${routeParam}`;

      // 🎓 بطاقة الطالب في الكروب - شكل مختلف تماماً عن بطاقة الكابتن
      const groupNoticeText = 
        `🎓 <b>${userMention} يبحث عن خط نقل</b>\n` +
        `📍 <b>المسار المطلوب:</b> ${finalOrigin} ⬅️ ${finalDestination}\n\n` +
        `✅ وجدنا (${matchedLines.length}) خط متوفر لهذا المسار!\n` +
        `<i>👇 تفاصيل الخطوط والحجز بالخاص مع البوت مباشرة:</i>\n\n` +
        `⚠️ <i>ملاحظة: هذه المجموعة للطلاب الي يحتاجون خطوط أو يريدون يسوون خطوط لتسهيل أمرهم. نحن غير مسؤولين عن أصحاب الخطوط أو عن الطلاب، وبالتوفيق للجميع 🌹</i>\n` +
        `⏳ <i>[ يختفي تلقائياً خلال 60 ثانية ]</i>`;

      const groupNoticeMarkup = {
        inline_keyboard: [
          [{ text: '🚌 استلام تفاصيل الخطوط بالخاص ⚡', url: routeLink }],
          [{ text: '🔔 نبّهني أول ما ينزل خط إضافي', url: `https://t.me/${BOT_USERNAME}?start=radar_${encodeURIComponent(finalOrigin)}_${encodeURIComponent(finalDestination)}` }],
          [
            { text: '🌐 تصفح الخطوط بالموقع', url: 'https://www.souqbaghdad.store/transport' },
            { text: '📢 انشر طلبك مجاناً', url: `https://t.me/${BOT_USERNAME}?start=pubtrans` }
          ]
        ]
      };

      await sendOrReplaceGroupMessage(chatId, groupNoticeText, groupNoticeMarkup, supabase, userMessageId, 60000);

      // أرسل البطاقة الكاملة بالخاص فوراً إذا فتح المستخدم البوت من قبل
      if (fromUser?.id) {
        try {
          const privateCard = buildTransportCard(matchedLines, 0, fromName, finalOrigin, finalDestination, false, 'route');
          await sendMessage(fromUser.id, privateCard.text, privateCard.markup);
        } catch(e) {}
      }
    } else {
      const card = buildTransportCard(matchedLines, 0, fromName, finalOrigin, finalDestination, false, 'route');
      await sendMessage(chatId, card.text, card.markup);
    }
    return;
  }

  // 🔔 In GROUP: If no matching line found -> Register seeker in DB (private DM only!)
  if (isGroup) {
    if (origin && destination) {
      try {
        await supabase.from('transport_requests').insert({
          telegram_chat_id: fromUser?.id ? String(fromUser.id) : null,
          telegram_user_id: fromUser?.id ? String(fromUser.id) : null,
          user_name: fromName,
          origin: finalOrigin,
          destination: finalDestination,
          raw_query: rawText,
          status: 'pending'
        });
      } catch(e) {}

      // رسالة ذكية ومفيدة بالكروب للطالب مع أزرار عملية
      const userMention = fromUser?.username ? `@${fromUser.username}` : fromName;
      const radarLink = `https://t.me/${BOT_USERNAME}?start=radar_${encodeURIComponent(finalOrigin)}_${encodeURIComponent(finalDestination)}`;
      const pubLink = `https://t.me/${BOT_USERNAME}?start=pubtrans`;
      const noLineGroupMsg =
        `🎓 <b>${userMention} — طلب خط نقل 🚌</b>\n` +
        `📍 <b>المسار المطلوب:</b> ${finalOrigin} ⬅️ ${finalDestination}\n\n` +
        `⚠️ <b>لا يوجد كابتن مسجل بهذا المسار المباشر حالياً.</b>\n` +
        `💡 <i>انشر طلبك مجاناً لنوصلك بالسائقين، أو فعّل الرادار لتنبيهك فور توفر خط!</i>\n\n` +
        `⏳ <i>[ تختفي الرسالة تلقائياً خلال 60 ثانية لحفظ نظافة الكروب ]</i>`;

      const noLineMarkup = {
        inline_keyboard: [
          [
            { text: '📢 انشر طلبي لمساري مجاناً 🚀', url: pubLink }
          ],
          [
            { text: '🔔 نبّهني بالخاص أول ما ينزل خط ⚡', url: radarLink }
          ],
          [
            { text: '🌐 تصفح خطوط النقل بالموقع', url: 'https://www.souqbaghdad.store/transport' },
            { text: '🚖 كابتن؟ اعرض خطك هنا', url: pubLink }
          ]
        ]
      };
      await sendOrReplaceGroupMessage(chatId, noLineGroupMsg, noLineMarkup, supabase, userMessageId, 60000);
    }
    return; // Stay silent otherwise!
  }

  // 🔔 In PRIVATE CHAT: If NO line matched this specific destination: Register request & politely inform student
  if (origin || destination) {
    try {
      await supabase.from('transport_requests').insert({
        telegram_chat_id: String(chatId),
        telegram_user_id: fromUser?.id ? String(fromUser.id) : null,
        user_name: fromName,
        origin: finalOrigin,
        destination: finalDestination,
        raw_query: rawText,
        status: 'pending'
      });
    } catch(e) {}

    const noMatchMsg = 
      `📝 <b>يا هلا ${fromName} 🌹 سجلت طلبك لمسار (${finalOrigin} ⬅️ ${finalDestination})</b>\n\n` +
      `🔍 <i>حالياً لا يوجد خط مباشر متوفر لنفس هذه الوجهة، وراح يوصلك تنبيه فوري بالخاص أول ما ينشر أي كابتن يمر بمسارك! ✨</i>`;

    const noMatchMarkup = {
      inline_keyboard: [
        [{ text: '💬 التحدث مع البوت بالخاص 🌹', url: `https://t.me/${BOT_USERNAME}` }],
        [
          { text: '🚌 تصفح جميع خطوط الموقع', url: 'https://www.souqbaghdad.store/transport' },
          { text: '🗑️ حذف هذا الرد', callback_data: 'del_group_msg' }
        ]
      ]
    };

    await sendMessage(chatId, noMatchMsg, noMatchMarkup);
    return;
  }

  // If user only wrote origin without destination in private chat (e.g. "محتاجة خط من المهندسين")
  if (origin && !destination) {
    const seekerState = {
      step: 'trans_seeker_dest',
      data: {
        origin: origin,
        raw_text: rawText
      }
    };
    await supabase.from('telegram_users').update({ bot_state: seekerState }).eq('telegram_chat_id', chatId);

    const askDestMsg = 
      `🚌 <b>يا هلا بيك عيوني ${fromName}! 🌹</b>\n\n` +
      `📍 حددنا منطقة انطلاقك: <b>${origin}</b>\n` +
      `🏛️ <b>إلى أين الوجهة؟</b>\n(اختر كليتك أو جامعتك من الأزرار أدناه، أو اكتب اسم وجهتك برسالة):`;

    const destButtons = [
      [{ text: '🎓 كلية الرافدين الجامعة', callback_data: 'seeker_dest_كلية الرافدين الجامعة' }, { text: '🏛️ الجامعة المستنصرية', callback_data: 'seeker_dest_الجامعة المستنصرية' }],
      [{ text: '🏢 الجامعة التكنولوجية', callback_data: 'seeker_dest_الجامعة التكنولوجية' }, { text: '🎓 جامعة بغداد (الجادرية)', callback_data: 'seeker_dest_جامعة بغداد' }],
      [{ text: '🏛️ جامعة النهرين', callback_data: 'seeker_dest_جامعة النهرين' }, { text: '🎓 كلية التراث الجامعة', callback_data: 'seeker_dest_كلية التراث الجامعة' }],
      [{ text: '🎓 كلية الاسراء الجامعة', callback_data: 'seeker_dest_كلية الاسراء الجامعة' }, { text: '🏢 جامعة دجلة', callback_data: 'seeker_dest_جامعة دجلة' }],
      [{ text: '🎓 جامعة الفراهيدي', callback_data: 'seeker_dest_جامعة الفراهيدي' }, { text: '🏢 جامعة اوروك', callback_data: 'seeker_dest_جامعة اوروك' }],
      [{ text: '🚌 تصفح جميع الخطوط بالموقع', url: 'https://www.souqbaghdad.store/transport' }]
    ];

    await sendMessage(chatId, askDestMsg, { inline_keyboard: destButtons });
    return;
  }

  // If user only wrote "محتاج خط" without specifying origin or destination in private chat
  if (!origin && !destination) {
    await showRadarAreaPicker(chatId, supabase);
    return;
  }
}

async function notifyWaitingStudents(ad: any, supabase: any) {
  if (!ad || (ad.category !== 'transport' && ad.type !== 'transport')) return;
  // 🛡️ Passenger requests are NOT offers from captains! Never notify waiting students about other students' requests!
  if (ad.type === 'request') return;
  const adText = `${ad.title || ''} ${ad.location || ''} ${ad.description || ''}`.toLowerCase();
  
  try {
    const { data: pendingRequests, error } = await supabase
      .from('transport_requests')
      .select('*')
      .eq('status', 'pending');

    if (error || !pendingRequests || pendingRequests.length === 0) return;

    // Deduplication set to ensure each student gets strictly ONE notification per published ad
    const notifiedUserIds = new Set<string>();

    for (const req of pendingRequests) {
      // 🛡️ Never notify publisher about their own ad
      if (ad.seller_id && req.user_id && String(req.user_id) === String(ad.seller_id)) continue;
      if (ad.chat_id && req.telegram_chat_id && String(req.telegram_chat_id) === String(ad.chat_id)) continue;

      const orig = req.origin || '';
      const dest = req.destination || '';

      const isOrigMatch = isLocationMatch(orig, adText);
      const isDestMatch = isDestinationMatch(dest, adText, ad.city || '');

      if (isOrigMatch && isDestMatch) {
        const targetChatId = String(req.telegram_chat_id || req.telegram_user_id);
        if (notifiedUserIds.has(targetChatId)) continue;
        notifiedUserIds.add(targetChatId);

        let userTag = req.user_name || 'عزيزنا';
        if (!userTag.startsWith('@') && req.telegram_user_id) {
          userTag = `<a href="tg://user?id=${req.telegram_user_id}">${userTag}</a>`;
        }

        const notifyMsg = 
          `📍 <b>إشعار رادار: توفر خط نقل يطابق مسارك</b>\n\n` +
          `مرحباً بك ${userTag}\n` +
          `توفر خط جديد يمر بالمسار المطلوب:\n` +
          `• <b>المسار:</b> ${ad.title}\n` +
          `• <b>المناطق:</b> ${ad.location || 'بغداد'}\n` +
          `• <b>الأجرة:</b> ${formatTgPrice(ad.price)}\n` +
          (ad.phone ? `• <b>هاتف التواصل:</b> <code>${ad.phone}</code>\n\n` : '\n') +
          `يمكنك إرسال طلب حجز مقعد أو التواصل المباشر عبر الخيارات أدناه:`;

        const cleanPhone = (ad.phone || '').replace(/[^0-9+]/g, '');
        const waPhone = cleanPhone.startsWith('07') ? '964' + cleanPhone.substring(1) : cleanPhone.replace('+', '');
        const contactRow: any[] = [];
        if (waPhone) contactRow.push({ text: 'تواصل عبر واتساب', url: `https://wa.me/${waPhone}` });

        const drvRepPhone = cleanPhone || 'nophone';
        const drvRepTitle = encodeURIComponent((ad.title || 'سائق خط').substring(0, 20));
        const markup = {
          inline_keyboard: [
            [{ text: 'إرسال طلب حجز مقعد للكابتن', callback_data: `req_seat_${ad.id}` }],
            contactRow,
            [{ text: 'تفاصيل الخط بالموقع', url: 'https://www.souqbaghdad.store/transport' }],
            [{ text: 'تم الاتفاق وتوقف التنبيه', callback_data: `stop_alert_${req.id}` }],
            [{ text: 'إبلاغ عن مشكلة', callback_data: `rep_drv_${drvRepTitle}_${drvRepPhone}` }]
          ].filter(r => r.length > 0)
        };

        // NEVER send radar notifications to group chats! Send strictly to student's private DM!
        const privateTarget = req.telegram_user_id || (req.telegram_chat_id && !String(req.telegram_chat_id).startsWith('-') ? req.telegram_chat_id : null);
        if (privateTarget) {
          try {
            await sendMessage(privateTarget, notifyMsg, markup);
          } catch(e) {}
        }

        await supabase
          .from('transport_requests')
          .update({ 
            status: 'notified', 
            notified_at: new Date().toISOString() 
          })
          .eq('id', req.id);
      }
    }
  } catch(e) {
    console.error('Error in notifyWaitingStudents:', e);
  }
}

async function sendMediaGroup(chatId: string | number, photoUrls: string[], caption: string) {
  const media = photoUrls.slice(0, 10).map((url, index) => {
    const item: any = { type: 'photo', media: url };
    if (index === 0 && caption) {
      item.caption = caption;
      item.parse_mode = 'HTML';
    }
    return item;
  });
  const body: any = { chat_id: chatId, media };
  const res = await fetch(`${tgUrl}/sendMediaGroup`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return res.json();
}

async function editMessageCaption(chatId: string | number, messageId: number, caption: string, replyMarkup?: any) {
  const body: any = { chat_id: chatId, message_id: messageId, caption, parse_mode: 'HTML' };
  if (replyMarkup) body.reply_markup = replyMarkup;
  const res = await fetch(`${tgUrl}/editMessageCaption`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return res.json();
}

async function editMessageText(chatId: string | number, messageId: number | string, text: string, replyMarkup?: any) {
  const body: any = { chat_id: chatId, message_id: messageId, text, parse_mode: 'HTML', disable_web_page_preview: true };
  if (replyMarkup) body.reply_markup = replyMarkup;
  const res = await fetch(`${tgUrl}/editMessageText`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return res.json();
}

async function editChannelMessage(chatId: string | number, messageId: number, captionOrText: string, replyMarkup?: any) {
  try {
    let res = await editMessageCaption(chatId, messageId, captionOrText, replyMarkup);
    if (!res?.ok) {
      console.warn(`editMessageCaption failed on ${chatId} (msg: ${messageId}):`, res?.description, '- trying editMessageText...');
      res = await editMessageText(chatId, messageId, captionOrText, replyMarkup);
    }
    return res;
  } catch (err) {
    console.error(`editChannelMessage exception on ${chatId}:`, err);
    try {
      return await editMessageText(chatId, messageId, captionOrText, replyMarkup);
    } catch(e) {
      return { ok: false, description: String(e) };
    }
  }
}

async function findAndEditPartnerChannelPost(
  channelId: string | number,
  shortId: string,
  soldCaption: string,
  soldButtons: any
): Promise<number | null> {
  if (!channelId || !shortId) return null;
  const cleanShortId = shortId.trim().toUpperCase();

  for (let msgId = 1; msgId <= 50; msgId++) {
    try {
      const res = await fetch(`${tgUrl}/editMessageReplyMarkup`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: channelId, message_id: msgId, reply_markup: soldButtons })
      });
      const data = await res.json();
      if (data?.ok && data.result) {
        const cap = (data.result.caption || data.result.text || '').toUpperCase();
        if (cap.includes(cleanShortId)) {
          console.log(`[PARTNER SCAN] Matched ad #${cleanShortId} in ${channelId} at msgId ${msgId}! Updating caption...`);
          await editMessageCaption(channelId, msgId, soldCaption, soldButtons);
          return msgId;
        } else {
          if (data.result.reply_markup) {
            await fetch(`${tgUrl}/editMessageReplyMarkup`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ chat_id: channelId, message_id: msgId, reply_markup: data.result.reply_markup })
            });
          }
        }
      }
    } catch(e) {}
  }
  return null;
}



