            const pName = b.passenger_name || `طالب ${idx + 1}`;
            const pOrigin = b.route_origin || 'نقطة صعوده';
            rows.push([
              { text: `👤 ${idx + 1}. ${pName} — 📍 ${pOrigin}`, callback_data: `hub_cpt_one_m_${b.id}` }
            ]);
